    Write-Host "Checking $domain..."
    $checkResult = cmd /c "curl.exe --proxy http://127.0.0.1:7897 -k -s -m 15 https://api.cloudflare.com/client/v4/registrar/domains/$domain/prices" | ConvertFrom-Json

