    $checkResult = cmd /c "curl.exe --proxy http://127.0.0.1:7897 -k -s -m 15 https://api.cloudflare.com/client/v4/registrar/domains/$domain/prices" | ConvertFrom-Json

    if ($checkResult.success) {
        Write-Host "$domain pricing:"
        $checkResult.result.pricing | ForEach-Object { Write-Host "- $($_.type): $($_.price.value)" }
    } else {
        Write-Host "Error for $domain: $($checkResult.errors.message)"
    }
}"
  ],
  "cwd": "E:\OneDrive\文档\个人主页 2",
  "justification": "检查两个域名的注册价格并准备注册",
